import{_ as t,a as o,b as r}from"./chunks/OOP2values.BXGNZAUw.js";import{_ as a}from"./chunks/Install17.CwCXrGHM.js";import{_ as n,o as i,c as s,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Libre 2","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/libre2.md","filePath":"troubleshoot/libre2.md"}'),h={name:"troubleshoot/libre2.md"};function c(p,e,u,d,m,b){return i(),s("div",null,[...e[0]||(e[0]=[l('<div class="info custom-block"><p class="custom-block-title">Libre 2 EU</p><p>Only the European version of Libre 2 is supported by xDrip.<br> If you want to use Libre 2 from another geographical area, you can have data sent to xDrip from <a href="./../install/libre2patch.html">another app</a>.</p></div><br><h2 id="patched-app" tabindex="-1">Patched app <a class="header-anchor" href="#patched-app" aria-label="Permalink to &quot;Patched app&quot;">​</a></h2><p>You can build your patched app in Europe in agreement with directive 2009/24/EC Art.6 (application may vary from country to country). Germany has an exception in the vendor app EULA chapter 6.<br> Distribution of the patched app is not authorized.</p><p>You will find explanations on how to generate the app in <a href="https://github.com/search" target="_blank" rel="noreferrer">GitHub</a> searching <code>xDrip-Patch</code>.</p><p>Current sensor must be started with the patched app in order for the app to connect to it.<br> Your phone Bluetooth must have been enabled and the app prerequisites satisfied <strong>before</strong> you started the sensor. If you started a sensor without the correct app prerequisites you might not be able to enable alarms and hence receive data.</p><p>xDrip will automatically receive data from the patched app using the specific hardware data source <a href="./../install/libre2patch.html">Libre2 (patched App)</a>.</p><h4 id="check-connection" tabindex="-1">Check connection <a class="header-anchor" href="#check-connection" aria-label="Permalink to &quot;Check connection&quot;">​</a></h4><p>The patched app must be connected to the sensor if you want xDrip to receive data from it. Usually, when it is not, you will see an exclamation mark top left.</p><img src="'+t+'" style="zoom:75%;"><p>If your system was working correctly and this happened unexpectedly, try to restart your phone, put it in airplane mode, turn off then on Bluetooth to see if it can recover connection.</p><p>Scanning the sensor can be a good idea. If the sensor doesn&#39;t give data after scanning it, it might be defective.</p><p>Opening the menu might give you information on missing prerequisites for the app to connect to the sensor.</p><h4 id="prerequisites-to-connection" tabindex="-1">Prerequisites to connection <a class="header-anchor" href="#prerequisites-to-connection" aria-label="Permalink to &quot;Prerequisites to connection&quot;">​</a></h4><ul><li>Android location service must be allowed, <strong>Always</strong>. Make the patched app always allowed (example below for xDrip)<br><img src="'+a+'" style="zoom:80%;"></li><li>Phone must be on <a href="./../install/prerequisites.html#phone-time-accuracy">automatic time and time zone</a></li><li>At least one of the three alarms <strong>must be activated</strong> in the patched app</li><li>Bluetooth must be <strong>switched on</strong></li><li>Alarms and reminders (sounds) must be <strong>authorized</strong> (Android settings - Apps)</li><li>Notifications must be <strong>authorized</strong> (Android settings - Apps)</li><li>Idle screen notifications must be <strong>authorized</strong> (Android settings - Apps)</li></ul><br><h2 id="direct-connection" tabindex="-1">Direct Connection <a class="header-anchor" href="#direct-connection" aria-label="Permalink to &quot;Direct Connection&quot;">​</a></h2><p>When you want to try xDrip connecting directly to a Libre 2 sensor for the first time and you&#39;re not sure you will be able to get the system working, it is strongly recommended that you do this on the last day of your current sensor.<br> xDrip will not break the sensor, it will only prevent the vendor app or the reader from receiving alarms, and if you rely on these, you might be left with a sensor behaving like a Libre 1.</p><p>More information about Libre 2 direct is <a href="./libre2direct.html">here</a></p><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><p>The device you used to start the sensor must be shielded (microwave oven - switched off) to avoid it interacting with the xDrip pairing process. It will show the connection lost icon.</p><img src="'+o+'" style="zoom:75%;"><p>If you installed xDrip on the same phone you used to start and scan the sensor, it is recommended that you uninstall the vendor app as it will prevent you from connecting to the sensor Bluetooth and will negatively interact with the NFC scans. You can reinstall the app when xDrip is connected to the sensor; it will obviously not have sensor alarms anymore.</p><p>If you don&#39;t want to remove the vendor app, you must disable its location authorization from Android settings.<br><strong>xDrip must be authorized, always.<br> The vendor app must NOT be authorized, ever.</strong></p><p>Note that if you keep the vendor app on your phone, you will be required to select between it and xDrip every time you scan the sensor with NFC. This might generate reading errors in xDrip.</p><h4 id="sensor-scan-errors" tabindex="-1">Sensor scan errors <a class="header-anchor" href="#sensor-scan-errors" aria-label="Permalink to &quot;Sensor scan errors&quot;">​</a></h4><p>Make sure you have <a href="./../install/libreNFC.html#configure-nfc">set up</a> xDrip NFC correctly.<br> Scanning takes more time with xDrip. Once you find the correct location of your phone&#39;s NFC antenna, go to the right spot and hold still.<br> You cannot scan less than 30 seconds after the previous scan.</p><h4 id="cannot-connect-to-the-sensor" tabindex="-1">Cannot connect to the sensor <a class="header-anchor" href="#cannot-connect-to-the-sensor" aria-label="Permalink to &quot;Cannot connect to the sensor&quot;">​</a></h4><p>Check <a href="./../use/OOP.html#oop2">OOP2</a> is installed, enable <a href="./../use/misc.html#oop2">no calibration</a>, <a href="./../use/stopsensor.html#libre">stop sensor</a> and restart from <a href="./../install/libre2.html#connect-to-the-sensor">here</a>.</p><p>Scan repeatedly every 2 minutes for 10 minutes then leave the system alone for 20 minutes.</p><p>After repeated scans you should see values in xDrip.<br> You should also see values in the OOP2 app.</p><img src="'+r+'" style="zoom:74%;"><p>If you don&#39;t see values after scanning:</p><ul><li>Double check you did <strong>NOT</strong> enable <a href="./../use/misc.html#out-of-process-algorithm">OOP1</a> by mistake</li><li>Make sure xDrip has <a href="./../install/install.html#enable-location">location access authorized</a>, <strong>always</strong></li><li>Restart your phone and retry</li></ul><br><p>Check the <a href="./librebridge.html">troubleshooting</a> page if necessary.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.06.15" target="_blank" rel="noreferrer"><em>Last modified 18/06/2023</em></a></p>',38)])])}const w=n(h,[["render",c]]);export{v as __pageData,w as default};
